                control.fail(
                    cursor,
                    Fault::new(SwiftRunFailureKind::Invariant, "swift_run_layout_overflow"),
                    None,
                )
            })?;
            control.construction = Some(control.admit(
                SwiftReservationCategory::Construction,
                construction,
                cursor,
            )?);
            control.check(cursor)
        })

